def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    net_change = v1 - v2

    return {
        "value": net_change,
        "trace": {
            "v1": v1,
            "v2": v2,
            "net_change": net_change,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": None
            }
        }
    }
